if(empty($_SESSION['se_csrf']))$_SESSION['se_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['se_csrf'];
function seh($value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
function se_link(array $extra=[]):string{return '/thidua_danhgia.php?'.http_build_query(array_merge($_GET,$extra));}
try{$month=se_month((string)($_GET['month']??date('Y-m')));}catch(Throwable$e){http_response_code(400);exit(seh($e->getMessage()));}
$monthStore=load_json(se_path($month),['records'=>[]]);$records=$monthStore['records']??[];$visible=[];$ownId='';
foreach($staff as$s){$id=(string)$s['id'];$r=$records[$id]??se_blank($s,$month,$config);if(se_can_read($r,$user))$visible[$id]=['staff'=>$s,'record'=>$r];if(se_own($r['assignment'],$user))$ownId=$id;}
if(!$visible&&!se_admin($user)){http_response_code(403);exit('Chưa liên kết mã nhân sự hoặc chưa được phân công đánh giá. Liên hệ quản trị cấu hình tài khoản trong Thi đua → Đánh giá CBGVNV.');}
if($view==='settings'&&!se_admin($user))$view='month';
