if($id!==''&&!isset($visible[$id])){http_response_code(403);exit('Hồ sơ ngoài phạm vi được giao.');}
$record=$visible[$id]['record']??null;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(se_readonly($user))throw new RuntimeException('Tài khoản chỉ xem không được cập nhật.');if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Phiên làm việc không hợp lệ.');
  $action=(string)($_POST['action']??'');
  if($action==='config'){
   se_update(DATA_PATH.'/staff_evaluation/config.json',fn($old)=>se_configure($old,$user,$_POST,$staff,$users),se_defaults());
  }else{
   if(!$record)throw new RuntimeException('Chọn nhân sự trước khi lưu.');$source=$action==='sync'?se_source_rows($visible[$id]['staff'],$month,$staff):[];
   se_update(se_path($month),function($store)use($id,$visible,$month,$config,$user,$action,$source){
    $current=$store['records'][$id]??se_blank($visible[$id]['staff'],$month,$config);
    $store['records'][$id]=se_transition($current,$user,$action,$_POST,$source,se_config());return$store;
   },['records'=>[]]);
  }
  flash('Đã lưu.');header('Location: '.se_link());exit;
 }catch(Throwable$e){$error=$e->getMessage();http_response_code(422);
  if($record&&in_array($_POST['action']??'',['save_self','submit'],true)&&se_own($record['assignment'],$user)&&se_editable($record)){
   foreach(['strengths','limits','explanation']as$field)if(is_string($_POST[$field]??null))$record[$field]=substr($_POST[$field],0,4000);
   foreach($record['criteria']as$c){$cid=$c['id'];$v=$_POST['scores'][$cid]??null;if(is_scalar($v))$record['self_scores'][$cid]=is_numeric($v)&&is_finite((float)$v)?(float)$v:null;$v=$_POST['evidence'][$cid]??null;if(is_string($v))$record['evidence_notes'][$cid]=substr($v,0,2000);}
  }}
}
if($view==='annual'){
 $from=(string)($_GET['from_month']??substr($month,0,4).'-01');$to=(string)($_GET['to_month']??substr($month,0,4).'-12');try{se_month($from);se_month($to);if($from>$to||substr($from,0,4)!==substr($to,0,4))throw new RuntimeException('Chọn khoảng tháng trong cùng năm công tác.');}catch(Throwable$e){http_response_code(400);exit(seh($e->getMessage()));}
 $annual=[];for($m=$from;$m<=$to;$m=date('Y-m',strtotime($m.'-01 +1 month'))){$r=load_json(se_path($m),['records'=>[]])['records'][$id]??null;if($r&&se_can_read($r,$user))$annual[$m]=$r;}
 if(($_GET['export']??'')==='csv'){
  header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="danhgia_'.$from.'_'.$to.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Tháng','Mã nhân sự','Họ tên','Trạng thái','Điểm tự đánh giá','Điểm thẩm định','Điểm duyệt','Phiên bản']);
  foreach($annual as$m=>$r){$row=[$m,$r['staff_id'],$r['name'],$r['status'],se_total($r['self_scores'],$r['criteria']),se_total($r['review_scores'],$r['criteria']),se_total($r['approved_scores'],$r['criteria']),$r['criteria_version']['id']];$row=array_map(fn($s)=>preg_match('/^[=+\-@\t\r]/u',(string)$s)?"'".$s:$s,$row);fputcsv($out,$row);}fclose($out);exit;
 }
}
$status=['draft'=>'Nháp','returned'=>'Cần bổ sung','submitted'=>'Chờ thẩm định','reviewed'=>'Chờ phê duyệt','locked'=>'Đã duyệt · khóa'];
function se_hidden(array $r,string $csrf,string $action):void{echo'<input type="hidden" name="csrf" value="'.seh($csrf).'"><input type="hidden" name="revision" value="'.seh($r['revision']).'"><input type="hidden" name="action" value="'.seh($action).'">';}
function se_user_select(string $name,string $value,array $users):void{echo'<select name="'.seh($name).'"><option value="">Chưa phân công</option>';foreach($users as$u)if(($u['active']??true)&&($u['role']??'')!=='viewer')echo'<option value="'.seh($u['id']).'" '.((string)$u['id']===$value?'selected':'').'>'.seh(($u['name']??'').' · '.($u['username']??'')).'</option>';echo'</select>';}
?>
