<?php if(se_admin($user)&&se_editable($record)&&($record['criteria_version']['id']!==se_version($config,$month)['id']||$record['assignment']!==se_assignment($config,$id))):?><details class="se-section"><summary>Cập nhật cấu hình mới cho hồ sơ nháp</summary><form method="post"><?php se_hidden($record,$csrf,'apply_config');?><p>Bộ tiêu chí/phân công mới chỉ áp dụng khi xác nhận. Điểm đã nhập sẽ được xóa khỏi bản nháp và lưu trong lịch sử.</p><label>Lý do<input name="reason" required></label><button>Áp dụng cấu hình hiện hành</button></form></details><?php endif;?><?php if(empty($record['criteria_version']['active'])):?><div class="se-alert">Bộ tiêu chí dự thảo: có thể lưu nháp; chưa gửi hoặc phê duyệt chính thức.</div><?php endif;?><?php if(!empty($record['return_reason'])):?><div class="se-alert">Yêu cầu bổ sung: <?=seh($record['return_reason'])?></div><?php endif;?><?php if($record['assignment']['external']):?><div class="se-alert">Hồ sơ thuộc diện trình cấp có thẩm quyền ngoài trường. Không phê duyệt nội bộ.</div><?php endif;?>
<h3>Nhiệm vụ – Sản phẩm</h3><p class="se-muted">Nhiệm vụ nhiều tháng khai theo mốc sản phẩm của tháng này. Nhiệm vụ cá nhân đề xuất cần được người phụ trách xác nhận.</p>
<?php foreach($record['tasks']as$task):?><article class="se-task"><div class="se-heading"><strong><?=seh($task['title'])?></strong><span><?=!$task['assigned']?'Chờ xác nhận giao việc':($task['accepted']?'Đã nghiệm thu':'Đã giao')?></span></div><p>Sản phẩm: <?=seh($task['product'])?><br>Yêu cầu chất lượng: <?=seh($task['quality'])?><br>Hạn/mốc: <?=seh($task['due'])?> · Khối lượng: <?=seh($task['weight'])?></p>
<?php if(!empty($task['cancelled'])):?><p>Đã hủy: <?=seh($task['adjustment']??'')?></p><?php elseif($own&&$editable):?><form method="post"><?php se_hidden($record,$csrf,'task_result');?><input type="hidden" name="task_id" value="<?=seh($task['id'])?>"><label>Kết quả thực hiện<textarea name="result" rows="2"><?=seh($task['result'])?></textarea></label><div class="se-grid"><label>Liên kết sản phẩm/minh chứng<input type="url" name="url" value="<?=seh($task['url'])?>" placeholder="https://..."></label><label>Ngày hoàn thành<input type="date" name="completed" value="<?=seh($task['completed'])?>"></label></div><button class="secondary">Lưu kết quả nhiệm vụ</button></form><?php else:?><p><?=nl2br(seh($task['result']))?></p><?php if($task['url']):?><a href="<?=seh($task['url'])?>" target="_blank" rel="noopener noreferrer">Mở sản phẩm/minh chứng</a><?php endif;?><?php endif;?>
<?php if(empty($task['cancelled'])&&($review||$approve)&&in_array($record['status'],['draft','returned','submitted'],true)):?><form method="post" class="se-grid"><?php se_hidden($record,$csrf,'task_accept');?><input type="hidden" name="task_id" value="<?=seh($task['id'])?>"><label>Ý kiến xác nhận/nghiệm thu<input name="reason" required></label><label class="se-check"><input type="checkbox" name="accept_result" value="1"> Nghiệm thu kết quả đã nộp</label><button class="secondary">Xác nhận nhiệm vụ</button></form><?php endif;?><?php if(empty($task['cancelled'])&&($review||$approve)&&$editable):?><details><summary>Điều chỉnh/hủy nhiệm vụ</summary><form method="post"><?php se_hidden($record,$csrf,'task_adjust');?><input type="hidden" name="task_id" value="<?=seh($task['id'])?>"><label>Sản phẩm<textarea name="product" required><?=seh($task['product'])?></textarea></label><label>Chất lượng<textarea name="quality" required><?=seh($task['quality'])?></textarea></label><label>Hạn/mốc tháng<input type="date" name="due" value="<?=seh($task['due'])?>" required></label><label>Lý do<input name="reason" required></label><label class="se-check"><input type="checkbox" name="cancel" value="1"> Hủy nhiệm vụ (giữ lịch sử)</label><button class="secondary">Lưu điều chỉnh</button></form></details><?php endif;?><?php if(!empty($task['acceptance'])):?><small>Nghiệm thu: <?=seh($task['acceptance'])?></small><?php endif;?></article><?php endforeach;?>
<?php if(($own||$review||$approve)&&$editable):?><details class="se-section"><summary>+ <?=$own?'Đề xuất':'Giao'?> nhiệm vụ tháng</summary><form method="post"><?php se_hidden($record,$csrf,'task_add');?><label>Tên nhiệm vụ<input name="title" maxlength="500" required></label><div class="se-grid"><label>Sản phẩm/mốc cần bàn giao<textarea name="product" rows="2" required></textarea></label><label>Yêu cầu chất lượng<textarea name="quality" rows="2" required></textarea></label><label>Hạn/mốc sản phẩm trong tháng<input name="due" type="date" min="<?=seh($month)?>-01" max="<?=seh(date('Y-m-t',strtotime($month.'-01')))?>" required></label><label>Khối lượng được giao<input name="weight" type="number" min=".01" max="1000" step=".01" value="1" required></label></div><button>Thêm nhiệm vụ</button></form></details><?php endif;?></section>
<section class="se-card"><div class="se-heading"><h3>Minh chứng từ các phân hệ</h3><?php if(($own||$review||$approve)&&$editable):?><form method="post"><?php se_hidden($record,$csrf,'sync');?><button class="secondary">Cập nhật minh chứng</button></form><?php endif;?></div><p class="se-muted">Nguồn hiện hỗ trợ: dự giờ, kiểm tra hồ sơ, chấm công, thành tích. Dữ liệu chỉ làm căn cứ đối chiếu, không tự đổi điểm. Lần cập nhật: <?=seh($record['sources_at']??'Chưa cập nhật')?>.</p><?php if(!$record['sources']):?><p>Chưa có minh chứng liên kết. Có thể bổ sung sản phẩm và giải trình trong phiếu.</p><?php else:?><ul><?php foreach($record['sources']as$source):?><li><a href="<?=seh($source['url'])?>" target="_blank" rel="noopener"><?=seh($source['type'].' · '.$source['date'])?></a> — <?=seh($source['label'])?> <small><?=seh($source['matched'])?></small></li><?php endforeach;?></ul><?php endif;?></section>
<section class="se-card"><h3>Phiếu đánh giá tháng</h3><?php if($own&&$editable):?><form method="post"><?php se_hidden($record,$csrf,'save_self');?><?php else:?><div><?php endif;?><div class="se-table-wrap"><table class="se-score-table"><thead><tr><th>Tiêu chí · Hướng dẫn</th><th>Tối đa</th><th>Tự đánh giá</th><th>Thẩm định</th><th>Duyệt</th><th>Căn cứ/giải trình</th></tr></thead><tbody><?php foreach($record['criteria']as$c):$cid=$c['id'];?><tr><td><strong><?=seh($cid.'. '.$c['name'])?></strong><details><summary>Hướng dẫn chấm</summary><?=seh($c['guide'])?></details></td><td><?=seh($c['max'])?></td><td><?php if($own&&$editable):?><input class="se-score" type="number" step=".01" min="0" max="<?=seh($c['max'])?>" name="scores[<?=seh($cid)?>]" value="<?=seh($record['self_scores'][$cid]??'')?>" aria-label="<?=seh('Tự đánh giá '.$cid)?>" placeholder="—"><?php else:?><?=seh($record['self_scores'][$cid]??'—')?><?php endif;?></td><td><?=seh($record['review_scores'][$cid]??'—')?></td><td><?=seh($record['approved_scores'][$cid]??'—')?></td><td><?php if($own&&$editable):?><textarea name="evidence[<?=seh($cid)?>]" rows="2" aria-label="<?=seh('Căn cứ '.$cid)?>"><?=seh($record['evidence_notes'][$cid]??'')?></textarea><?php else:?><?=nl2br(seh($record['evidence_notes'][$cid]??''))?><?php endif;?></td></tr><?php endforeach;?></tbody><tfoot><tr><th>Tổng</th><th>100</th><?php foreach(['self_scores','review_scores','approved_scores']as$col):?><th><?=seh(se_total($record[$col],$record['criteria'])??'Chưa đủ căn cứ')?></th><?php endforeach;?><td></td></tr></tfoot></table></div>
<div class="se-grid"><?php foreach(['strengths'=>'Ưu điểm','limits'=>'Hạn chế và hướng khắc phục','explanation'=>'Giải trình/trường hợp đặc biệt, nhiệm vụ kiêm nhiệm']as$key=>$label):?><label><?=seh($label)?><textarea name="<?=seh($key)?>" rows="3" <?=$own&&$editable?'':'readonly'?>><?=seh($record[$key])?></textarea></label><?php endforeach;?></div>
<?php if($own&&$editable):?><div class="se-actions"><button>Lưu nháp</button><button name="action" value="submit" class="success" <?=empty($record['criteria_version']['active'])?'disabled':''?>>Gửi đánh giá</button></div><?php endif;?><?php if($own&&$editable):?></form><?php else:?></div><?php endif;?>
<?php if(($review&&$record['status']==='submitted')||($approve&&$record['status']==='reviewed'&&!$record['assignment']['external'])):$stage=$record['status']==='submitted'?'review':'approve';$base=$stage==='review'?$record['self_scores']:$record['review_scores'];?><form method="post" class="se-section"><?php se_hidden($record,$csrf,$stage);?><h3><?=$stage==='review'?'Thẩm định hồ sơ':'Phê duyệt và khóa tháng'?></h3><div class="se-grid"><?php foreach($record['criteria']as$c):?><label><?=seh($c['id'].' · '.$c['name'])?><input type="number" min="0" max="<?=seh($c['max'])?>" step=".01" name="scores[<?=seh($c['id'])?>]" value="<?=seh($base[$c['id']]??'')?>" required></label><?php endforeach;?></div><label>Nhận xét và lý do điều chỉnh điểm<textarea name="reason" rows="3" required></textarea></label><div class="se-actions"><button class="success"><?=$stage==='review'?'Hoàn tất thẩm định':'Phê duyệt và khóa'?></button><button name="action" value="return" class="secondary">Trả bổ sung</button></div></form><?php endif;?>
<?php if($approve&&$record['status']==='locked'):?><details class="se-section"><summary>Mở lại hồ sơ đã khóa</summary><form method="post"><?php se_hidden($record,$csrf,'reopen');?><label>Lý do mở lại<textarea name="reason" required></textarea></label><button class="secondary">Mở lại · giữ bản chốt cũ</button></form></details><?php endif;?>
<?php if($record['review_note']):?><p>Thẩm định: <?=nl2br(seh($record['review_note']))?></p><?php endif;?><?php if($record['approval_note']):?><p>Phê duyệt: <?=nl2br(seh($record['approval_note']))?></p><?php endif;?>
<details class="se-section"><summary>Lịch sử xử lý (<?=count($record['history'])?>)</summary><?php foreach(array_reverse($record['history'])as$h):?><p><?=seh($h['at'].' · '.$h['name'].' · '.$h['action'].' · '.$h['from'].' → '.$h['to'])?><br><?=seh($h['reason'])?></p><?php endforeach;?></details></section>
<?php else:?><section class="se-card">Chưa có nhân sự trong CSDL. Cập nhật CSDL CBGVNV trước khi đánh giá.</section><?php endif;?>
<footer class="se-footer"><a href="/danhgia.php?view=overview">Tra cứu hồ sơ đánh giá trước đây</a><span>Đánh giá tháng và xét thi đua là các kết quả riêng.</span></footer></main></body></html>
